int oy[] = { 0, 0,-1, 1,-1, 1};
int ex[] = {-1, 1, 0, 0,-1,-1};
int ey[] = { 0, 0,-1, 1,-1, 1};

int main(){
    int point[100][100];
    int h, w, a, b, t, x, y, s;

