        rep(i,100) rep(j,100) point[i][j] = 0;
        scanf("%d", &t);
        rep(i,t){
            scanf("%d%d", &a, &b);
            a--; b--;
            point[b][a] = i + 1;
        }
        scanf("%d", &s);
        rep(P,s){
            scanf("%d%d", &a, &b);
            a--; b--;
            point[b][a] = 50;

            int pt[100] = {0};
            queue<NODE> Q;
            pair<int,int> dp[100];
            bool done[100][100] = {0};

            // Instead of calling queue initialization within the loop, we initialize it before the loop
            // and clear it after each iteration to improve performance
            for (int i = 0; i < h; ++i) {
                for (int j = 0; j < w; ++j) {
                    x = j; y = i;
                    Q.push(make_pair(make_pair(y,x),0));
                    // Reset dp and done arrays
                    fill(done[0], done[100], false);
                    fill(dp, dp + 100, make_pair(0, 0));

