                        if(point[q.Y][q.X]){
                            dp[q.depth].first++;
                            dp[q.depth].second = point[q.Y][q.X];
                        }

                        // Use a single loop to process neighbors based on the depth
                        int* ox_dir = (q.Y % 2 == 1) ? ox : ex;
                        int* oy_dir = (q.Y % 2 == 1) ? oy : ey;

